site.css:
* { box-sizing: border-box; }
html { background: #FAF8F2; }
body { margin: 0; background: #FAF8F2; color: #292b2a; font-family: "Hiragino Kaku Gothic ProN", "Yu Gothic", Meiryo, sans-serif; }
.portfolio { width: 100%; }
.site-header { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; padding: 1.2rem 5vw; color: #275FA8; }
.studio-name { margin: 0; font-size: 1rem; font-weight: 600; letter-spacing: .08em; }
.header-note { margin: 0; color: #62645f; font-size: .75rem; letter-spacing: .04em; }
.featured-work { margin: 0; }
.studio-hero-visual { width: 100%; height: 62vw; max-height: 690px; min-height: 320px; margin: 0; overflow: hidden; background: #dedbd2; }
.studio-hero-visual img { display: block; width: 100%; height: 100%; object-fit: cover; object-position: 52% 48%; }
.work-caption { padding: 1.2rem 8vw 2.8rem; }
.work-type, .work-year, .image-note { margin: 0; color: #62645f; font-size: .78rem; letter-spacing: .04em; }
.work-caption h1 { margin: .25rem 0 .35rem; color: #275FA8; font-size: clamp(1.65rem, 3vw, 2.5rem); font-weight: 500; letter-spacing: .06em; }
.image-note { margin-top: 1rem; font-size: .68rem; }
.works-index { padding: 1.8rem 8vw 3.5rem; border-top: 1px solid #dedbd2; }
.works-index h2 { margin: 0 0 1.3rem; color: #275FA8; font-size: 1.1rem; font-weight: 500; letter-spacing: .08em; }
.work-entry { padding: 1rem 0; border-top: 1px solid #dedbd2; }
.work-entry h3 { margin: .25rem 0; font-size: 1.35rem; font-weight: 500; letter-spacing: .04em; }
.site-footer { padding: 1.2rem 8vw; border-top: 1px solid #dedbd2; color: #62645f; font-size: .75rem; }
.site-footer p { margin: 0; }
@media (min-width: 760px) {
  .site-header { padding: 1.5rem 6vw; }
  .studio-hero-visual { height: 60vw; max-height: 760px; }
  .work-caption { padding: 1.3rem 12vw 3.2rem; }
  .works-index { padding: 2rem 12vw 4rem; }
  .site-footer { padding-right: 12vw; padding-left: 12vw; }
}
@media (max-width: 420px) {
  .site-header { align-items: flex-start; flex-direction: column; gap: .35rem; padding: 1rem 6vw; }
  .studio-hero-visual { height: 75vw; min-height: 0; }
  .work-caption { padding: .85rem 6vw 2rem; }
  .works-index { padding: 1.4rem 6vw 2.6rem; }
}
img{display:block;width:100%;object-fit:cover;object-position:52% 48%!important}.studio-hero-visual>img{aspect-ratio:16/9;height:auto}@media(max-width:600px){.studio-hero-visual>img{aspect-ratio:4/3}}
